dashboard.definition:
{
 "title": "Threat Hunting",
 "description": "Reconnaissance, beaconing, Internet exposure and data movement hunts built on the Windows Defender Firewall connection log.",
 "visualizations": {
  "hdr": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## Threat Hunting\nPre-built hunts over the firewall log: reconnaissance, command and control, exposure and data movement.",
    "fontSize": "large",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "kpi_denied_out": {
   "type": "splunk.singlevalue",
   "title": "Denied outbound to Internet",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('denied_out') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#e5484d"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_inbound": {
   "type": "splunk.singlevalue",
   "title": "Inbound accepted from Internet",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('inbound_ext') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#f5a623"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_peers": {
   "type": "splunk.singlevalue",
   "title": "External peers",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('ext_peers') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#4fa3ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_out": {
   "type": "splunk.singlevalue",
   "title": "Data sent",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('mb_out') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "#31c2c9",
    "unit": "MB",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_recon": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 1 — Reconnaissance\nDenied traffic concentrated in a short window. Adjust the threshold with the input above.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_portscan": {
   "type": "splunk.table",
   "title": "Vertical port scans (many ports, one target)",
   "dataSources": {
    "primary": "ds_portscan"
   },
   "options": {
    "count": 8,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Click a row to pivot on the scanning address.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_peer_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_peer=$row.src_ip.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_sweep": {
   "type": "splunk.table",
   "title": "Horizontal sweeps (one port, many targets)",
   "dataSources": {
    "primary": "ds_sweep"
   },
   "options": {
    "count": 8,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Click a row to pivot on the scanning address.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_peer_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_peer=$row.src_ip.value$",
      "newTab": false
     }
    }
   ]
  },
  "hdr_c2": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 2 — Command and control\nOutbound sessions repeating at a near constant interval. The lower the jitter, the more automated the traffic.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_beacon": {
   "type": "splunk.table",
   "title": "Beaconing candidates",
   "dataSources": {
    "primary": "ds_beacon"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "jitter = standard deviation / average interval. Below 0.1 is almost never human. Click a row to pivot on the destination.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_peer_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_peer=$row.dest_ip.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_denied_out": {
   "type": "splunk.table",
   "title": "Hosts repeatedly denied outbound",
   "dataSources": {
    "primary": "ds_denied_out"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Click a row to open the Host 360 view.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.host.value$",
      "newTab": false
     }
    }
   ]
  },
  "hdr_expo": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 3 — Exposure\nWhat the Internet can reach, and which ports only a couple of machines ever use.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_exposed": {
   "type": "splunk.table",
   "title": "Services accepting public inbound traffic",
   "dataSources": {
    "primary": "ds_exposed"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Click a row to open the Host 360 view.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.host.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_rare": {
   "type": "splunk.table",
   "title": "Rare outbound destination ports",
   "dataSources": {
    "primary": "ds_rare_ports"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  },
  "hdr_data": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### 4 — Data movement",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_exfil": {
   "type": "splunk.table",
   "title": "Largest outbound transfers to external peers",
   "dataSources": {
    "primary": "ds_exfil"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Click a row to pivot on the receiving address.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_peer_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_peer=$row.dest_ip.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_new_peers": {
   "type": "splunk.table",
   "title": "Most recently observed external peers",
   "dataSources": {
    "primary": "ds_new_peers"
   },
   "options": {
    "count": 10,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Click a row to pivot on the address.",
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_peer_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_peer=$row.dest_ip.value$",
      "newTab": false
     }
    }
   ]
  }
 },
 "dataSources": {
  "ds_host_list": {
   "type": "ds.search",
   "options": {
    "query": "| tstats count WHERE index IN `windows_firewall_index` sourcetype=\"windows:pfirewall\" BY host | fields host | sort host"
   },
   "name": "Host list"
  },
  "ds_traffic": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_traffic` $tk_exclusion$ | search host IN ($ms_host$)"
   },
   "name": "Traffic base search"
  },
  "ds_kpi": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| stats count(eval(action=\"blocked\" AND direction=\"outbound\" AND dest_scope=\"external\")) AS denied_out, count(eval(action=\"allowed\" AND direction=\"inbound\" AND src_scope=\"external\")) AS inbound_ext, dc(eval(if(dest_scope=\"external\", dest_ip, null()))) AS ext_peers, sum(eval(if(direction=\"outbound\", bytes_out, 0))) AS bo | eval mb_out = round(bo/1048576, 1)"
   },
   "name": "KPI"
  },
  "ds_portscan": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search action=blocked | bin _time span=5m | stats dc(dest_port) AS distinct_ports, dc(dest_ip) AS targets, count AS attempts, values(transport) AS transport BY _time, host, src_ip | where distinct_ports >= $tk_scan_threshold$ | eval time = strftime(_time, \"%F %T\") | table time host src_ip distinct_ports targets attempts transport | sort - distinct_ports | head 25"
   },
   "name": "Port scans"
  },
  "ds_sweep": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search action=blocked | bin _time span=5m | stats dc(dest_ip) AS targets, dc(dest_port) AS distinct_ports, count AS attempts BY _time, host, src_ip | where targets >= $tk_scan_threshold$ | eval time = strftime(_time, \"%F %T\") | table time host src_ip targets distinct_ports attempts | sort - targets | head 25"
   },
   "name": "Network sweeps"
  },
  "ds_beacon": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search action=allowed direction=outbound dest_scope=external | sort 0 host dest_ip _time | streamstats current=f last(_time) AS previous_time BY host, dest_ip | eval interval = _time - previous_time | where isnotnull(interval) AND interval > 5 | stats count AS connections, avg(interval) AS avg_interval, stdev(interval) AS stdev_interval, dc(dest_port) AS ports, values(dest_port) AS dest_port, sum(bytes_out) AS bytes_out BY host, dest_ip | where connections >= 10 AND avg_interval >= 20 | eval jitter = round(stdev_interval / avg_interval, 3), avg_interval = round(avg_interval, 1) | where jitter < 0.25 | table host dest_ip dest_port connections avg_interval jitter bytes_out | sort + jitter | head 25"
   },
   "name": "Beaconing candidates"
  },
  "ds_denied_out": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search action=blocked direction=outbound dest_scope=external | stats count AS denied, dc(dest_ip) AS destinations, dc(dest_port) AS ports, values(dest_service) AS services BY host | sort - denied | head 15"
   },
   "name": "Denied outbound"
  },
  "ds_exposed": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search action=allowed direction=inbound src_scope=external | stats count AS accepted, dc(src_ip) AS sources, values(dest_service) AS service BY host, dest_port, transport | sort - sources | head 20"
   },
   "name": "Exposed services"
  },
  "ds_rare_ports": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search direction=outbound dest_scope=external | eval service = coalesce(dest_service, \"unknown\") | stats count AS connections, dc(host) AS hosts, values(action) AS action BY dest_port, transport, service | where hosts <= 2 AND connections >= 5 | sort + hosts, - connections | head 20"
   },
   "name": "Rare destination ports"
  },
  "ds_exfil": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search direction=outbound dest_scope=external action=allowed | stats sum(bytes_out) AS bytes_out, count AS packets, dc(dest_port) AS ports, values(dest_service) AS service BY host, dest_ip | eval mb_out = round(bytes_out/1048576, 1) | where mb_out >= 100 | table host dest_ip service ports packets mb_out | sort - mb_out | head 20"
   },
   "name": "Outbound volume"
  },
  "ds_new_peers": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_traffic",
    "query": "| search dest_scope=external | stats min(_time) AS first_seen, max(_time) AS last_seen, count AS connections, values(dest_service) AS service BY host, dest_ip, dest_port | eval age_min = round((now() - first_seen)/60, 1), first_seen = strftime(first_seen, \"%F %T\"), last_seen = strftime(last_seen, \"%F %T\") | sort + age_min | head 20"
   },
   "name": "Newly observed external peers"
  }
 },
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-24h@h,now"
   }
  },
  "input_host": {
   "type": "input.multiselect",
   "title": "Host",
   "dataSources": {
    "primary": "ds_host_list"
   },
   "options": {
    "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
    "token": "ms_host",
    "defaultValue": [
     "*"
    ],
    "valuePrefix": "\"",
    "valueSuffix": "\"",
    "delimiter": ","
   },
   "context": {
    "formattedConfig": {
     "number": {
      "prefix": ""
     }
    },
    "formattedStatics": ">statics | formatByType(formattedConfig)",
    "statics": [
     {
      "label": "All",
      "value": "*"
     }
    ],
    "label": ">primary | seriesByName(\"host\") | renameSeries(\"label\") | formatByType(formattedConfig)",
    "value": ">primary | seriesByName(\"host\") | renameSeries(\"value\") | formatByType(formattedConfig)"
   }
  },
  "input_threshold": {
   "type": "input.dropdown",
   "title": "Scan threshold",
   "options": {
    "token": "tk_scan_threshold",
    "defaultValue": "50",
    "items": [
     {
      "label": "Aggressive (20)",
      "value": "20"
     },
     {
      "label": "Balanced (50)",
      "value": "50"
     },
     {
      "label": "Conservative (100)",
      "value": "100"
     },
     {
      "label": "Very conservative (250)",
      "value": "250"
     }
    ]
   }
  },
  "input_excl": {
   "type": "input.dropdown",
   "title": "Noise filter",
   "options": {
    "token": "tk_exclusion",
    "defaultValue": "`ip_whitelist`",
    "items": [
     {
      "label": "Exclude whitelisted ranges",
      "value": "`ip_whitelist`"
     },
     {
      "label": "No filtering",
      "value": "| noop"
     }
    ]
   }
  }
 },
 "layout": {
  "type": "grid",
  "options": {
   "width": 1440,
   "submitButton": false,
   "backgroundColor": "#0e1319"
  },
  "structure": [
   {
    "item": "hdr",
    "type": "block",
    "position": {
     "x": 0,
     "y": 0,
     "w": 1440,
     "h": 80
    }
   },
   {
    "item": "kpi_denied_out",
    "type": "block",
    "position": {
     "x": 0,
     "y": 80,
     "w": 360,
     "h": 150
    }
   },
   {
    "item": "kpi_inbound",
    "type": "block",
    "position": {
     "x": 360,
     "y": 80,
     "w": 360,
     "h": 150
    }
   },
   {
    "item": "kpi_peers",
    "type": "block",
    "position": {
     "x": 720,
     "y": 80,
     "w": 360,
     "h": 150
    }
   },
   {
    "item": "kpi_out",
    "type": "block",
    "position": {
     "x": 1080,
     "y": 80,
     "w": 360,
     "h": 150
    }
   },
   {
    "item": "hdr_recon",
    "type": "block",
    "position": {
     "x": 0,
     "y": 230,
     "w": 1440,
     "h": 60
    }
   },
   {
    "item": "viz_portscan",
    "type": "block",
    "position": {
     "x": 0,
     "y": 290,
     "w": 720,
     "h": 330
    }
   },
   {
    "item": "viz_sweep",
    "type": "block",
    "position": {
     "x": 720,
     "y": 290,
     "w": 720,
     "h": 330
    }
   },
   {
    "item": "hdr_c2",
    "type": "block",
    "position": {
     "x": 0,
     "y": 620,
     "w": 1440,
     "h": 60
    }
   },
   {
    "item": "viz_beacon",
    "type": "block",
    "position": {
     "x": 0,
     "y": 680,
     "w": 792,
     "h": 380
    }
   },
   {
    "item": "viz_denied_out",
    "type": "block",
    "position": {
     "x": 792,
     "y": 680,
     "w": 648,
     "h": 380
    }
   },
   {
    "item": "hdr_expo",
    "type": "block",
    "position": {
     "x": 0,
     "y": 1060,
     "w": 1440,
     "h": 60
    }
   },
   {
    "item": "viz_exposed",
    "type": "block",
    "position": {
     "x": 0,
     "y": 1120,
     "w": 720,
     "h": 380
    }
   },
   {
    "item": "viz_rare",
    "type": "block",
    "position": {
     "x": 720,
     "y": 1120,
     "w": 720,
     "h": 380
    }
   },
   {
    "item": "hdr_data",
    "type": "block",
    "position": {
     "x": 0,
     "y": 1500,
     "w": 1440,
     "h": 40
    }
   },
   {
    "item": "viz_exfil",
    "type": "block",
    "position": {
     "x": 0,
     "y": 1540,
     "w": 720,
     "h": 380
    }
   },
   {
    "item": "viz_new_peers",
    "type": "block",
    "position": {
     "x": 720,
     "y": 1540,
     "w": 720,
     "h": 380
    }
   }
  ],
  "globalInputs": [
   "input_time",
   "input_host",
   "input_threshold",
   "input_excl"
  ]
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     }
    }
   }
  }
 }
}
